import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react'

import type { ScrollBoxRenderable } from '@opentui/core'

import type { RunAttention } from '@dltech/atlas-client/transcript'
import { EEntryKind, type PendingRow, type TranscriptModel } from '../../store'
import { NOTHING_IN_BACKGROUND, type BackgroundWork } from '../background-wait'
import { useAppearance } from '../hooks/use-appearance'
import { useEntryWindow } from '../hooks/use-entry-window'
import { useTranscriptFollow } from '../hooks/use-transcript-follow'
import { useHiddenVerticalScrollbar } from '../hide-scrollbar'
import { TRANSCRIPT_PADDING } from '../theme'
import { useTranscriptViewport } from '../transcript-viewport-store'
import { applyTranscriptBounds } from '../viewport-rows-store'
import type { ContainerMove } from '../../composition/container-move'
import { BootBlockView } from './boot-block'
import { PendingBlock } from './blocks/pending-block'
import { RunAttentionSection } from './blocks/run-attention-section'
import { openedInjectionsOf, type OpenedInjections } from './blocks/system-context-expansion'
import { openedSubsetOf, type OpenedSubsets } from './blocks/tool-run-expansion'
import { EntryView } from './entry-view'
import { JumpToBottom, NewDivider, UNSEEN_ANCHOR_ID } from './new-divider'
import { PeekLine } from './peek-line'
import type { RetryWait } from '../retry-countdown'
import { IDLE_TURN, type TurnClock } from '../turn-clock'
import { RotatingLine, type Rotating } from './rotating-line'
import { EWorkingVerb, WaitingLine, WorkingLine } from './working-line'

export type { RetryWait }

const NOTHING_PENDING: readonly PendingRow[] = Object.freeze([])

function DerivedTranscript(props: {
  model: TranscriptModel
  width: number
  now: number
  cwd: string
  turn?: TurnClock
  rotating?: Rotating | null
  cloudConnected?: boolean
  reconnecting?: boolean
  updating?: string
  waking?: boolean
  disconnected?: boolean
  stale?: boolean
  reconnectingSince?: number | null
  lastSeenAt?: number | null
  onReconnect?: () => void
  anchorKey?: string | null
  sends?: number
  pending?: readonly PendingRow[]
  boot?: { move: ContainerMove; cancel: (() => void) | undefined } | null
  background?: BackgroundWork
  waitingSince?: number | null
  accountLabel?: string
  attention?: RunAttention | null
  onRetry?: () => void
  onDismissFailure?: () => void
  onResume?: () => void
  opened?: ReadonlySet<string>
  onToggle?: (key: string) => void
  onNearTop?: () => void
}): React.ReactNode {
  useAppearance()
  const { model } = props
  const turn = props.turn ?? IDLE_TURN
  const anchorKey = props.anchorKey ?? null
  const anchorIndex = model.entries.findIndex((entry) => entry.key === anchorKey)
  const peekKeys = useMemo(
    () =>
      new Set(
        model.entries
          .filter((entry) => entry.kind === EEntryKind.OperatorSaid)
          .map((entry) => entry.key),
      ),
    [model.entries],
  )
  const scroller = useRef<ScrollBoxRenderable | null>(null)
  const windowing = useEntryWindow({
    entries: model.entries,
    scroller,
    anchorIndex,
    width: props.width,
    ...(props.onNearTop === undefined ? {} : { onNearTop: props.onNearTop }),
  })

  const firstKey = useRef<string | null>(null)
  React.useLayoutEffect(() => {
    const first = model.entries[0]?.key ?? null
    const previous = firstKey.current
    firstKey.current = first
    if (previous === null || first === previous) return

    const box = scroller.current
    if (box === null) return
    windowing.pinToKey({ key: previous, offset: box.scrollTop })
  }, [model.entries, windowing])
  const follow = useTranscriptFollow({
    scroller,
    anchorId: anchorIndex >= 0 ? UNSEEN_ANCHOR_ID : null,
    sends: props.sends ?? 0,
    cloudConnected: props.cloudConnected ?? false,
    peekKeys,
    onTick: windowing.handleTick,
    ...(windowing.active ? { offsetOfKey: windowing.offsetOfKey } : {}),
  })
  const handleScroller = useHiddenVerticalScrollbar(follow.scroller)

  useEffect(() => {
    const box = follow.scroller.current?.viewport
    applyTranscriptBounds({ top: box?.y ?? 0, rows: box?.height ?? 0 })
  })
  const viewport = useTranscriptViewport()
  const peeked = model.entries.find((entry) => entry.key === viewport.peekKey) ?? null

  const [ownOpened, setOwnOpened] = useState<ReadonlySet<string>>(() => new Set<string>())
  const handleOwnToggle = useCallback((key: string) => {
    setOwnOpened((current) => {
      const next = new Set(current)
      if (!next.delete(key)) next.add(key)
      return next
    })
  }, [])

  const opened = props.opened ?? ownOpened
  const handleToggle = props.onToggle ?? handleOwnToggle
  const openedSubsets = useMemo((): OpenedSubsets => new WeakMap(), [])
  const openedInjections = useMemo((): OpenedInjections => new WeakMap(), [])

  const peekLine =
    viewport.tailing || peeked === null ? null : (
      <PeekLine
        text={peeked.text}
        width={props.width}
        onJumpTo={() => follow.handleJumpTo(peeked.key)}
      />
    )

  const mounted: React.ReactNode[] = []
  windowing.sections.forEach((section, sectionIndex) => {
    if (section.kind === 'spacer') {
      mounted.push(<box key={`spacer:${sectionIndex}`} height={section.height} flexShrink={0} />)
      return
    }
    for (let index = section.span.start; index < section.span.end; index += 1) {
      const entry = model.entries[index]
      if (entry === undefined) continue
      mounted.push(
        <box
          key={entry.key}
          id={entry.key}
          flexDirection="column"
          opacity={props.disconnected === true || props.stale === true ? 0.4 : 1}
        >
          {index === anchorIndex ? (
            <box id={UNSEEN_ANCHOR_ID} flexDirection="column">
              {index > 0 ? <NewDivider width={props.width} /> : null}
            </box>
          ) : null}
          <EntryView
            entry={entry}
            width={props.width}
            expanded={opened.has(entry.key)}
            {...(entry.kind === EEntryKind.ToolsRan
              ? {
                  opened: openedSubsetOf({
                    cache: openedSubsets,
                    run: entry.run,
                    opened,
                  }),
                }
              : {})}
            {...(entry.kind === EEntryKind.SystemContext
              ? {
                  opened: openedInjectionsOf({
                    cache: openedInjections,
                    entry,
                    opened,
                  }),
                }
              : {})}
            onToggle={handleToggle}
            cwd={props.cwd}
            continues={model.entries[index - 1]?.kind === EEntryKind.ToolsRan}
          />
        </box>,
      )
    }
  })

  return (
    <box flexDirection="column" flexGrow={1} flexShrink={1} flexBasis={0}>
      {peekLine}
      <scrollbox
        ref={handleScroller}
        flexGrow={1}
        flexShrink={1}
        flexBasis={0}
        focusable={false}
        stickyScroll
        stickyStart="bottom"
        viewportCulling
        contentOptions={{ paddingRight: TRANSCRIPT_PADDING }}
      >
        {mounted}

        <RunAttentionSection
          model={model}
          turn={turn}
          width={props.width}
          attention={props.attention ?? null}
          accountLabel={props.accountLabel}
          onRetry={props.onRetry}
          onDismiss={props.onDismissFailure}
          onResume={props.onResume}
        />

        {model.failure === null && props.rotating !== null && props.rotating !== undefined ? (
          <box flexDirection="row" marginTop={1} marginBottom={1}>
            <RotatingLine rotating={props.rotating} now={props.now} />
          </box>
        ) : model.failure === null && props.disconnected === true ? (
          <box flexDirection="row" marginTop={1} marginBottom={1}>
            <WorkingLine
              elapsedMs={0}
              outputTokens={0}
              interrupting={false}
              verb={EWorkingVerb.Disconnected}
              {...(props.lastSeenAt === undefined ? {} : { lastSeenAt: props.lastSeenAt })}
              {...(props.onReconnect === undefined ? {} : { onReconnect: props.onReconnect })}
            />
          </box>
        ) : model.failure === null && model.streaming && turn.startedAt !== null ? (
          <box flexDirection="row" marginTop={1} marginBottom={1}>
            <WorkingLine
              elapsedMs={props.now - turn.startedAt}
              outputTokens={turn.outputTokens}
              interrupting={turn.interrupting}
              verb={
                props.waking === true
                  ? EWorkingVerb.Waking
                  : props.reconnecting === true
                    ? EWorkingVerb.Reconnecting
                    : turn.reasoning
                      ? EWorkingVerb.Thinking
                      : EWorkingVerb.Working
              }
              {...(props.updating === undefined ? {} : { reconnectingAs: props.updating })}
              retry={turn.retry}
            />
          </box>
        ) : props.reconnecting === true && props.stale !== true ? (
          <box flexDirection="row" marginTop={1} marginBottom={1}>
            <WorkingLine
              elapsedMs={0}
              outputTokens={0}
              interrupting={false}
              verb={EWorkingVerb.Reconnecting}
              {...(props.updating === undefined ? {} : { reconnectingAs: props.updating })}
              since={props.reconnectingSince ?? null}
            />
          </box>
        ) : (
          <WaitingLine
            work={props.background ?? NOTHING_IN_BACKGROUND}
            since={props.waitingSince ?? null}
          />
        )}

        <PendingBlock rows={props.pending ?? NOTHING_PENDING} width={props.width} />

        {props.boot === null || props.boot === undefined ? null : (
          <BootBlockView
            move={props.boot.move}
            cancellable={props.boot.cancel !== undefined}
            width={props.width}
          />
        )}
      </scrollbox>

      {viewport.tailing ? null : (
        <JumpToBottom width={props.width} onJump={follow.handleJumpToBottom} />
      )}
    </box>
  )
}

export const Transcript = React.memo(DerivedTranscript)
