import {
  EExecutionLocation,
  ERunner,
  ESubscriptionStatus,
  prEventContent,
  type PrEditPolicy,
  type ThreadId,
} from '@dltech/atlas-core'
import {
  ECloudSandboxState,
  EOccurrenceUrgency,
  occurrenceOf,
  prEventNoticeOf,
  repoOfFrame,
  type CloudChannel,
  type PrEventFrame,
  type ThreadSummary,
} from '@dltech/atlas-harness'
import { PULL_REQUEST_SUBSCRIPTION_PROVIDER } from '@dltech/atlas-wire'

import type { CloudBridgeFactory } from './bridge-factory'

const isUrgent = ({ frame, policy }: { frame: PrEventFrame; policy: PrEditPolicy }): boolean =>
  occurrenceOf({ frame, policy })?.urgency === EOccurrenceUrgency.Now

const holdsActiveSubscription = (args: {
  summary: ThreadSummary
  repo: string
  number: number
}): boolean =>
  (args.summary.subscriptions ?? []).some((subscription) => {
    if (subscription.provider !== PULL_REQUEST_SUBSCRIPTION_PROVIDER) return false
    if (subscription.status !== ESubscriptionStatus.Active) return false
    const { target } = subscription
    if (typeof target !== 'object' || target === null) return false
    return (
      'repo' in target &&
      typeof target.repo === 'string' &&
      target.repo.toLowerCase() === args.repo.toLowerCase() &&
      'number' in target &&
      target.number === args.number
    )
  })

/**
 * Forwards a pull-request event into a parked cloud conversation as ordinary input. The active
 * local session's own routing already consumes frames for the conversation it tracks; this exists
 * for the thread the operator left in the cloud, whose sandbox has no live process to receive the event
 * itself. The vehicle is `channel.send` — the same frame operator input travels on — because the
 * agent registry's `say` only ever reaches a roster child, never the conversation's main thread.
 *
 * The dedupe key is sandbox liveness, not focus: a running sandbox streams the same SSE feed and
 * its own session consumes the frame natively, so forwarding while it runs would land the event
 * twice. Forward only when the sandbox is not Running — parked, stopped, unknown, or simply gone.
 * The API replays `pr-state` on reconnect but never `pr-event`, so a woken sandbox does not
 * re-receive what was forwarded to it.
 */
export type PrEventForwarder = {
  onPrEvent(frame: PrEventFrame): Promise<void>
}

export function createPrEventForwarder(args: {
  /** The merged local+cloud listing, so a cloud-only thread's stub row (with its wire subscriptions) resolves. */
  listThreads: (args: { project: string }) => Promise<readonly ThreadSummary[]>
  project: string
  bridge: CloudBridgeFactory
  activeThreadId: () => ThreadId | undefined
  editPolicy: () => PrEditPolicy
  apiProvisioned?: ((args: { threadId: ThreadId; runner: ERunner }) => boolean) | undefined
}): PrEventForwarder {
  const channels = new Map<ThreadId, CloudChannel>()
  const runners = new Map<ThreadId, ERunner>()
  const bridgeFor = (threadId: ThreadId) => {
    const runner = runners.get(threadId) ?? ERunner.Vercel
    return args.bridge({
      runner,
      apiProvisioned: args.apiProvisioned?.({ threadId, runner }) ?? false,
    })
  }

  const channelFor = (threadId: ThreadId): CloudChannel => {
    const held = channels.get(threadId)
    if (held !== undefined) return held
    const attached = bridgeFor(threadId).attach({ threadId })
    channels.set(threadId, attached.channel)
    return attached.channel
  }

  const cloudThreadsWatching = async (frame: PrEventFrame): Promise<readonly ThreadId[]> => {
    const repo = repoOfFrame(frame)
    const listed = await args.listThreads({ project: args.project }).catch(() => [])
    const active = args.activeThreadId()

    const watching = listed.filter(
      (summary) =>
        summary.executionLocation === EExecutionLocation.Cloud &&
        summary.id !== active &&
        holdsActiveSubscription({ summary, repo, number: frame.prNumber }),
    )

    for (const summary of watching) runners.set(summary.id, summary.runner ?? ERunner.Vercel)
    return watching.map((summary) => summary.id)
  }

  const parkedOrGone = async (threadId: ThreadId): Promise<boolean> => {
    const status = await bridgeFor(threadId)
      .sandboxes.find({ threadId })
      .catch(() => undefined)
    return status?.state !== ECloudSandboxState.Running
  }

  return {
    async onPrEvent(frame) {
      if (!isUrgent({ frame, policy: args.editPolicy() })) return
      const targets = await cloudThreadsWatching(frame)
      // Bare content, not prEventBlock: channel.send lands as operator-origin input and the
      // destination wraps it in <operator-said>, so a pre-wrapped system-notice would nest.
      const text = prEventContent(prEventNoticeOf(frame))

      for (const threadId of targets) {
        if (!(await parkedOrGone(threadId))) continue
        try {
          channelFor(threadId).send({ text })
        } catch {
          // A channel that refuses the frame is dropped, not retried: the next event re-attempts.
        }
      }
    },
  }
}
