import {
  EAgentRestart,
  EMessageOrigin,
  reportWakesParent,
  saidBody,
  type EReportKind,
  type EventDraft,
  type EventLogPort,
  type IdPort,
  type SaidFile,
  type SaidImage,
  type ThreadId,
} from '@dltech/atlas-core'

import { isTeammateType, type AgentType } from '../types'
import { isStepping, snapshotOf, type ChildState, type SteerMessage } from './child-state'
import type { ChildSteps } from './child-steps'
import { agentTypeNamed, type SupervisorDeps } from './deps'
import type { AgentJournal } from './agent-journal'
import { EAgentNotice, type AgentNoticeQueue } from './notices'
import type { AgentOutcome } from './port'
import { NOT_A_TEAMMATE, reportNotRecorded, retiredAgentType, unknownAgent } from './reasons'
import { recordRestart } from './record-restart'
import { childDirectory } from './relocate-children'
import type { AgentRoster } from './roster'

export type SayChannels = {
  log: EventLogPort
  ids: IdPort
  agentTypes: readonly AgentType[]
  roster: AgentRoster
  notices: AgentNoticeQueue
  journal: AgentJournal
  steps: ChildSteps
  deps: SupervisorDeps
}

type SaidArgs = {
  agentId: ThreadId
  threadId: ThreadId
  text: string
  images?: readonly SaidImage[] | undefined
  files?: readonly SaidFile[] | undefined
}

function deliver(args: Parameters<typeof deliverAdmitted>[0]): Promise<AgentOutcome> {
  return args.channels.steps.admit({
    threadId: args.child?.spawnedBy ?? args.args.threadId,
    start: () => deliverAdmitted(args),
  })
}

async function deliverAdmitted({
  args,
  via,
  child,
  known,
  channels,
}: {
  args: SaidArgs
  via: EMessageOrigin
  child: ChildState | undefined
  known: string
  channels: SayChannels
}): Promise<AgentOutcome> {
  const { log, ids, agentTypes, steps, deps } = channels

  if (child === undefined) return { ok: false, reason: known }

  const input = deps.input?.()
  if (isStepping(child)) {
    if (input !== undefined) {
      input.submit({
        threadId: args.agentId,
        text: args.text,
        ...(args.images === undefined ? {} : { images: args.images }),
        ...(args.files === undefined ? {} : { files: args.files }),
        via,
      })
      return { ok: true, snapshot: snapshotOf(child) }
    }

    const queued: SteerMessage = {
      text: args.text,
      images: args.images,
      files: args.files,
    }
    child.pending.push(queued)
    return { ok: true, snapshot: snapshotOf(child) }
  }

  const agentType = agentTypeNamed({ agentTypes, name: child.agentType })
  if (agentType === undefined) {
    return { ok: false, reason: retiredAgentType(child.agentType) }
  }

  const held = input?.hold({ threadId: args.agentId })
  try {
    if (input !== undefined) {
      input.submit({
        threadId: args.agentId,
        text: args.text,
        via,
        ...(args.images === undefined ? {} : { images: args.images }),
        ...(args.files === undefined ? {} : { files: args.files }),
      })
      await input.commit({
        threadId: args.agentId,
        append: async (drafts) => {
          await log.append({ threadId: args.agentId, runId: ids.nextRunId(), drafts })
          child.pending.length = 0
        },
      })
    } else {
      await log.append({
        threadId: args.agentId,
        runId: ids.nextRunId(),
        drafts: [{ ...saidBody({ text: args.text, images: args.images, files: args.files }), via }],
      })
    }
    child.projectDirectory ??= await childDirectory({ deps, threadId: child.spawnedBy })
    await recordRestart({ log, ids, child, via: EAgentRestart.Message })
    steps.take({
      child,
      agentType,
      step: ({ runner, signal, pause }) =>
        runner.runTurn({ threadId: args.agentId, signal, pause }),
    })
  } finally {
    held?.()
  }

  return { ok: true, snapshot: snapshotOf(child) }
}

export async function say(args: SaidArgs & SayChannels): Promise<AgentOutcome> {
  const child = args.roster.find(args.agentId)
  const owned = child === undefined || child.spawnedBy !== args.threadId ? undefined : child

  return deliver({
    args,
    via: EMessageOrigin.ParentAgent,
    child: owned,
    known: unknownAgent({ agentId: args.agentId, known: args.roster.list(args.threadId) }),
    channels: args,
  })
}

export async function reportToParent(
  args: { threadId: ThreadId; text: string; kind?: EReportKind | undefined } & SayChannels,
): Promise<AgentOutcome> {
  const caller = args.roster.find(args.threadId)
  if (caller === undefined || !isTeammateType(caller.agentType)) {
    return { ok: false, reason: NOT_A_TEAMMATE }
  }

  const draft: EventDraft = {
    type: 'agent-reported',
    agentId: caller.agentId,
    agentType: caller.agentType,
    intent: caller.intent,
    prose: args.text,
    ...(args.kind === undefined ? {} : { kind: args.kind }),
  }
  if (!reportWakesParent(args.kind)) {
    const recorded = await args.journal.record({ threadId: caller.spawnedBy, draft })
    if (!recorded.recorded) return { ok: false, reason: reportNotRecorded(recorded.cause) }
    return { ok: true, snapshot: snapshotOf(caller) }
  }

  const stamped = args.journal.stamp({ draft })
  const recorded = await args.journal.record({
    threadId: caller.spawnedBy,
    draft: stamped.arrived,
  })
  if (!recorded.recorded) return { ok: false, reason: reportNotRecorded(recorded.cause) }

  args.notices.queue({
    threadId: caller.spawnedBy,
    snapshot: snapshotOf(caller),
    kind: EAgentNotice.Report,
    draft: stamped.delivered,
  })

  return { ok: true, snapshot: snapshotOf(caller) }
}
