import { isTurnTaking, noticeIdOf, type EventDraft, type ThreadId } from '@dltech/atlas-core'

import type { InputBatch } from '../../intake/input-batch'
import type { AgentSnapshot } from './snapshot'

export enum EAgentNotice {
  Ending = 'ending',
  Report = 'report',
}

export type AgentNotice = {
  threadId: ThreadId
  snapshot: AgentSnapshot
  kind: EAgentNotice
  draft: EventDraft
  unloggedArrival?: EventDraft | undefined
  generation?: AbortSignal | undefined
}

export type AgentNoticeBatch = InputBatch & { notices: readonly AgentNotice[] }

const NOTHING_PENDING: readonly AgentNotice[] = Object.freeze([])

const NOTHING_ANNOUNCED: readonly AgentSnapshot[] = Object.freeze([])

export const draftsToAppend = (notices: readonly AgentNotice[]): readonly EventDraft[] =>
  notices.flatMap((notice) =>
    notice.unloggedArrival === undefined ? [notice.draft] : [notice.unloggedArrival, notice.draft],
  )

const NOTHING_NOTICED: ReadonlyMap<ThreadId, readonly AgentSnapshot[]> = new Map()

export class AgentNoticeQueue {
  private queued: readonly AgentNotice[] = NOTHING_PENDING
  private noticed: ReadonlyMap<ThreadId, readonly AgentSnapshot[]> = NOTHING_NOTICED
  private readonly listeners = new Set<() => void>()

  queue(notice: AgentNotice): void {
    this.settle([...this.queued, notice])
  }

  drain({ threadId }: { threadId: ThreadId }): readonly EventDraft[] {
    return draftsToAppend(this.take({ threadId, where: () => true }))
  }

  prepare({ threadId }: { threadId: ThreadId }): AgentNoticeBatch {
    const captured = this.queued.filter((notice) => notice.threadId === threadId)
    let acknowledged = false
    return {
      notices: captured,
      drafts: draftsToAppend(captured),
      wakesTurn: captured.some((notice) => isTurnTaking(notice.draft)),
      acknowledge: () => {
        if (acknowledged) return
        acknowledged = true
        this.takeCaptured(captured)
      },
    }
  }

  requeue(notice: AgentNotice): void {
    const id = noticeIdOf(notice.draft)
    if (id !== undefined && this.queued.some((held) => noticeIdOf(held.draft) === id)) return
    this.queue(notice)
  }

  takeCaptured(captured: readonly AgentNotice[]): void {
    if (captured.length === 0) return
    const leaving = new Set(captured)
    const kept = this.queued.filter((notice) => !leaving.has(notice))
    if (kept.length === this.queued.length) return
    this.settle(kept)
  }

  take({
    threadId,
    where,
  }: {
    threadId: ThreadId
    where: (notice: AgentNotice) => boolean
  }): readonly AgentNotice[] {
    const handed = this.queued.filter((notice) => notice.threadId === threadId && where(notice))
    if (handed.length === 0) return NOTHING_PENDING

    const leaving = new Set(handed)
    this.settle(this.queued.filter((notice) => !leaving.has(notice)))

    return handed
  }

  pending({ threadId }: { threadId: ThreadId }): readonly AgentSnapshot[] {
    return this.noticed.get(threadId) ?? NOTHING_ANNOUNCED
  }

  threadsAwaiting(): readonly ThreadId[] {
    return [
      ...new Set(
        this.queued.filter((notice) => isTurnTaking(notice.draft)).map((notice) => notice.threadId),
      ),
    ]
  }

  threadsQueued(): readonly ThreadId[] {
    return [...new Set(this.queued.map((notice) => notice.threadId))]
  }

  onNotice(listener: () => void): () => void {
    this.listeners.add(listener)
    return () => void this.listeners.delete(listener)
  }

  forget({ threadId }: { threadId: ThreadId }): void {
    const kept = this.queued.filter((notice) => notice.threadId !== threadId)
    if (kept.length === this.queued.length) return

    this.settle(kept)
  }

  forgetAgents({
    threadId,
    agentIds,
  }: {
    threadId: ThreadId
    agentIds: readonly ThreadId[]
  }): void {
    const removed = new Set(agentIds)
    const kept = this.queued.filter(
      (notice) => notice.threadId !== threadId || !removed.has(notice.snapshot.agentId),
    )
    if (kept.length === this.queued.length) return

    this.settle(kept)
  }

  /**
   * The snapshots are held rather than derived per call: pending backs a React external store,
   * which reads it on every render and requires a stable value between changes.
   */
  private settle(notices: readonly AgentNotice[]): void {
    this.queued = notices

    const byThread = new Map<ThreadId, AgentSnapshot[]>()
    for (const notice of notices) {
      const held = byThread.get(notice.threadId)
      if (held === undefined) byThread.set(notice.threadId, [notice.snapshot])
      else held.push(notice.snapshot)
    }
    this.noticed = byThread

    for (const listener of [...this.listeners]) listener()
  }
}
