import {
  backspaceSecretPrompt,
  commitSecretPrompt,
  ESecretCommit,
  openSecretPrompt,
  typeIntoSecretPrompt,
  type SecretPrompt,
  type SecretsPort,
  ESettingId,
  type SettingsResolution,
} from '@dltech/atlas-core'
import type { VercelCredentialStore, VercelWrite } from '@dltech/atlas-harness'
import type { KeyEvent, PasteEvent } from '@opentui/core'
import { usePaste } from '@opentui/react'
import { useCallback, useMemo, useState } from 'react'

import type { Span } from '../ui/components/spans'
import { isPrintable } from '../ui/keys/printable'
import { pastedText } from '../ui/pasted-text'
import { secretTargetOf } from '../ui/secret-target'
import { secretDisplay } from '../ui/settings-format'

export type SecretPromptControl = {
  prompt: SecretPrompt | null
  origin: string
  displayOf: (id: string) => Span | undefined
  open: (id: string) => boolean
  close: () => void
  refresh: () => void
  handleKey: (key: KeyEvent, current: SecretPrompt) => void
}

export function useSecretPrompt(args: {
  secrets: SecretsPort
  resolution: SettingsResolution
  vercel: VercelCredentialStore
  settle: (result: VercelWrite) => void
}): SecretPromptControl {
  const { secrets, resolution, vercel, settle } = args

  const [prompt, setPrompt] = useState<SecretPrompt | null>(null)
  const [reads, setReads] = useState(0)

  const displayOf = useCallback(
    (id: string): Span | undefined => {
      void reads
      if (vercel.signedIn()) {
        const held = vercel.snapshot()
        const shown = new Map<string, string | undefined>([
          [ESettingId.VercelToken, held.tokenSet ? 'configured' : undefined],
          [ESettingId.VercelTeamId, held.teamId],
          [ESettingId.VercelProjectId, held.projectId],
        ])
        if (shown.has(id)) {
          return secretDisplay({
            held: shown.get(id),
            masked: false,
            required: false,
            takesOne: true,
          })
        }
      }
      const target = secretTargetOf({ id, resolution })
      if (target === undefined) return undefined

      return secretDisplay({
        held: target.takesOne ? secrets.read(target.name) : undefined,
        masked: target.masked,
        required: target.required,
        takesOne: target.takesOne,
      })
    },
    [reads, resolution, secrets, vercel],
  )

  const open = useCallback(
    (id: string): boolean => {
      const target = secretTargetOf({ id, resolution })
      if (target === undefined || !target.takesOne) return false

      setPrompt(
        openSecretPrompt({
          name: target.name,
          label: target.label,
          masked: target.masked,
        }),
      )
      return true
    },
    [resolution],
  )

  const close = useCallback(() => setPrompt(null), [])

  const refresh = useCallback(() => {
    setReads((read) => read + 1)
    if (vercel.signedIn()) {
      void vercel
        .refresh()
        .catch(() => undefined)
        .then(() => setReads((read) => read + 1))
    }
  }, [vercel])

  const commit = useCallback(
    (current: SecretPrompt) => {
      const committed = commitSecretPrompt(current)
      if (vercel.signedIn() && committed.name === ESettingId.VercelToken) {
        const settled =
          committed.action === ESecretCommit.Save
            ? vercel.update({ token: committed.value })
            : vercel.clear()
        void settled.then((result) => {
          settle(result)
          setReads((read) => read + 1)
        })
      } else if (committed.action === ESecretCommit.Save) {
        secrets.write({ name: committed.name, value: committed.value })
      } else {
        secrets.remove(committed.name)
      }
      setReads((read) => read + 1)

      setPrompt(null)
    },
    [secrets, settle, vercel],
  )

  const handleKey = useCallback(
    (key: KeyEvent, current: SecretPrompt) => {
      if (key.name === 'escape') {
        setPrompt(null)
        return
      }

      if (key.name === 'return') {
        commit(current)
        return
      }

      if (key.name === 'backspace') {
        setPrompt(backspaceSecretPrompt(current))
        return
      }

      if (isPrintable(key)) {
        setPrompt(typeIntoSecretPrompt({ prompt: current, text: key.sequence ?? '' }))
      }
    },
    [commit],
  )

  usePaste(
    useCallback(
      (event: PasteEvent) => {
        if (prompt === null) return

        const pasted = pastedText(event)
        if (pasted.length === 0) return

        event.preventDefault()
        event.stopPropagation()
        setPrompt(typeIntoSecretPrompt({ prompt, text: pasted }))
      },
      [prompt],
    ),
  )

  const origin = secrets.origin()

  return useMemo(
    () => ({ prompt, origin, displayOf, open, close, refresh, handleKey }),
    [close, displayOf, handleKey, open, origin, prompt, refresh],
  )
}
