import {
  ESettingId,
  ESettingPage,
  formatFavourites,
  type EUsageWindow,
  type SecretPrompt,
  type TextPrompt,
} from '@dltech/atlas-core'
import type { SettingsWrite } from '@dltech/atlas-harness'
import type { KeyEvent } from '@opentui/core'
import { useCallback, useEffect, useMemo, useState, useSyncExternalStore } from 'react'

import { appearanceOf, applyAppearance, type Appearance } from '../ui/appearance'
import { type SettingsLoginState } from '../ui/settings-login-model'
import type { EFooterMeters } from '../ui/usage-meters'
import type { EThinkingVisibility } from '../store'
import {
  currentPage,
  openSettings,
  settingsModel,
  type SettingsModel,
  type SettingsState,
} from '../ui/settings-model'
import type { Span } from '../ui/components/spans'
import type { CloudSyncState } from '../ui/components/settings/cloud'
import type { AtlasApp } from './compose'
import { preferencesOf, type PlacementChooserShape } from './settings-preferences'
import { type CloudPageControl } from './use-cloud-page'
import { useSecretPrompt } from './use-secret-prompt'
import { type SettingsGithubControl } from './use-settings-github'
import { type SigningKeyControl } from './use-signing-key'
import { useSettingsCloud } from './use-settings-cloud'
import { useTextPrompt } from './use-text-prompt'
import { useSettingsKeys } from './use-settings-keys'

export type SettingsControl = {
  view: SettingsModel
  appearance: Appearance
  state: SettingsState | null
  prompt: SecretPrompt | null
  textPrompt: TextPrompt | null
  secretOf: (id: string) => Span | undefined
  secretOrigin: string
  origin: string
  problem: string | undefined
  cloudEmail: string | null
  cloudSignedIn: boolean
  cloudSignIn: SettingsLoginState
  cloudPage: CloudPageControl
  cloudUpload: CloudSyncState
  cloudDownload: CloudSyncState
  github: SettingsGithubControl
  signingKey: SigningKeyControl
  handleSignOut: () => void
  handleSignIn: () => void
  handleUpload: () => void
  handleDownload: () => void
  handleOpenSignInUrl: () => void
  handleOpenGithubUrl: () => void
  sidebarWidth: number
  sidebarFoldBelow: number
  autoCompactAtPercent: number
  autoRestart: boolean
  noticeSeconds: number
  paceReveal: boolean
  thinking: EThinkingVisibility
  tldrStatus: boolean
  footerMeters: EFooterMeters
  usageWarn: Record<EUsageWindow, number>
  modelFavourites: readonly string[]
  placementChooserShape: PlacementChooserShape
  handlePinModels: (favourites: readonly string[]) => void
  handleOpen: () => void
  handleOpenCloudSignIn: () => void
  handleDismiss: () => void
  handleSelect: (target: SettingsState) => void
  handleKey: (key: KeyEvent) => void
}

export function useSettings(args: {
  app: AtlasApp
  onChooseModel: (id: string) => void
}): SettingsControl {
  const { app, onChooseModel } = args
  useSyncExternalStore(app.settings.subscribe, app.settings.version)
  const held = app.settings.snapshot()

  const [state, setState] = useState<SettingsState | null>(null)
  const [refused, setRefused] = useState<string | null>(null)

  const view = useMemo(
    () =>
      settingsModel({
        definitions: app.settings.definitions,
        resolution: held.resolution,
        shadowedAgentTypes: app.agentTypes.shadowed,
        writeOriginOf: app.settings.writeOrigin,
      }),
    [app.agentTypes.shadowed, app.settings.definitions, app.settings.writeOrigin, held.resolution],
  )

  const { accent, density, composer, imageRows, fenceWrap, logo } = appearanceOf({
    resolution: held.resolution,
  })

  const appearance = useMemo(
    () => ({ accent, density, composer, imageRows, fenceWrap, logo }),
    [accent, composer, density, imageRows, fenceWrap, logo],
  )

  useEffect(() => {
    applyAppearance(appearance)
  }, [appearance])

  const settle = useCallback((result: SettingsWrite) => {
    setRefused(result.ok ? null : result.message)
  }, [])

  const vercel = app.cloud.vercel()
  const secret = useSecretPrompt({
    secrets: app.secrets,
    resolution: held.resolution,
    vercel,
    settle,
  })
  const text = useTextPrompt({
    settings: app.settings,
    settle,
    vercel,
    onVercelChanged: secret.refresh,
  })

  const reloadSettings = useCallback(() => {
    app.settings.reload()
    secret.refresh()
  }, [app.settings, secret.refresh])

  const {
    session: cloudSession,
    login: cloudLogin,
    cloudPage,
    github,
    signingKey,
    upload: cloudUpload,
    download: cloudDownload,
    readSession: readCloudSession,
    handleSignOut,
    handleUpload,
    handleDownload,
    handleOpenSignInUrl,
    handleOpenGithubUrl,
  } = useSettingsCloud({
    cloud: app.cloud,
    openUrl: app.openUrl,
    onSignedIn: secret.refresh,
    onDownloaded: reloadSettings,
  })

  const handleOpen = useCallback(() => {
    readCloudSession()
    secret.refresh()
    setState(openSettings())
  }, [readCloudSession, secret.refresh])

  const handleOpenCloudSignIn = useCallback(() => {
    readCloudSession()
    secret.refresh()
    const pageIndex = view.pages.findIndex((entry) => entry.page.id === ESettingPage.Cloud)
    setState({ ...openSettings(), pageIndex: Math.max(pageIndex, 0), rowIndex: 0 })
    cloudLogin.begin()
  }, [cloudLogin.begin, readCloudSession, secret.refresh, view.pages])

  const handlePinModels = useCallback(
    (favourites: readonly string[]) => {
      app.settings.set({
        id: ESettingId.ModelFavourites,
        value: formatFavourites(favourites),
      })
    },
    [app.settings],
  )

  const handleDismiss = useCallback(() => {
    setState(null)
    setRefused(null)
    secret.close()
    text.close()
    cloudLogin.stop()
    github.stop()
  }, [cloudLogin, github, secret, text])

  const onCloudPage =
    state !== null && currentPage({ state, model: view })?.page.id === ESettingPage.Cloud

  useEffect(() => {
    if (onCloudPage) github.refresh()
  }, [onCloudPage, cloudSession, github.refresh])

  useEffect(() => {
    if (onCloudPage) signingKey.refresh()
  }, [onCloudPage, cloudSession, github.connection?.login, signingKey.refresh])

  const handleSelect = useCallback(
    (target: SettingsState) => {
      cloudPage.handleDisarmAction()
      setState(target)
    },
    [cloudPage],
  )

  const { handleKey } = useSettingsKeys({
    app,
    view,
    state,
    select: setState,
    settle,
    secret,
    text,
    cloudPage,
    login: cloudLogin,
    github,
    signedIn: cloudSession !== null,
    onChooseModel,
    onDismiss: handleDismiss,
  })

  const preferences = useMemo(() => preferencesOf(held.resolution), [held.resolution])
  const problem = refused ?? held.problems[0]
  const origin = held.writesTo

  return useMemo(
    () => ({
      view,
      appearance,
      state,
      prompt: secret.prompt,
      textPrompt: text.prompt,
      secretOf: secret.displayOf,
      secretOrigin: secret.origin,
      origin,
      problem,
      cloudEmail: cloudSession?.email ?? null,
      cloudSignedIn: cloudSession !== null,
      cloudSignIn: cloudLogin.state,
      cloudPage,
      cloudUpload,
      cloudDownload,
      github,
      signingKey,
      handleSignOut,
      handleSignIn: cloudLogin.begin,
      handleUpload,
      handleDownload,
      handleOpenSignInUrl,
      handleOpenGithubUrl,
      ...preferences,
      handlePinModels,
      handleOpen,
      handleOpenCloudSignIn,
      handleDismiss,
      handleSelect,
      handleKey,
    }),
    [
      appearance,
      cloudDownload,
      cloudLogin.begin,
      cloudLogin.state,
      cloudPage,
      cloudSession,
      cloudUpload,
      github,
      signingKey,
      handleDismiss,
      handleDownload,
      handleKey,
      handleOpen,
      handleOpenCloudSignIn,
      handleOpenGithubUrl,
      handleOpenSignInUrl,
      handlePinModels,
      handleSelect,
      handleSignOut,
      handleUpload,
      origin,
      preferences,
      problem,
      secret,
      state,
      text,
      view,
    ],
  )
}
