import {
  AfterToolHook,
  AgentFileSystemPort,
  BeforeToolHook,
  BeforeTurnHook,
  DecisionPort,
  EventLogPort,
  OnThreadOpenHook,
  ProcessPort,
  ToolDefinition,
  WorkspaceFactsPort,
} from '@dltech/atlas-core'

import { registerClassifier } from '../classifier/register-classifier'
import { JevDecisionClient } from '../classifier/jev-client'
import { GitWorkspaceFacts } from '../classifier/workspace-facts'
import {
  instanceCachingFactory,
  portToken,
  registeredPortToken,
  resolveIfPossible,
  type DependencyContainer,
} from '../container/injection'
import {
  SessionRegistryToken,
  SkillSuggestionEnabledToken,
  WorkspaceRoot,
} from '../container/tokens'
import { FileReadStatePort } from '../files/read-state'
import { SkillRegistryPort } from '../skills/port'
import { InvalidateFactsHook } from './invalidate-facts'
import { MirrorPlanHook } from './mirror-plan'
import { OutsideProjectHook } from './outside-project'
import { PrewarmFactsHook } from './prewarm-facts'
import { ReadBeforeWriteHook } from './read-before-write'
import { ResolveProjectPathsHook } from './resolve-project-paths'
import { ServiceShapeHook } from './service-shape-hook'
import { RecordFileStateHook } from './record-file-state'
import { SkillSuggestionHook } from './skill-suggestion'
import { threadEnvironmentFrom } from './thread-environment'
import { OpenCheckoutHook, TrackCheckoutHook } from './track-checkout'
import { TrackWorktreeHook } from './track-worktree'

const checkoutObserverOf = (resolver: DependencyContainer) => ({
  process: resolver.resolve(registeredPortToken(ProcessPort)),
  log: resolver.resolve(registeredPortToken(EventLogPort)),
})

export function registerBuiltinHooks({ container }: { container: DependencyContainer }): void {
  container.register(registeredPortToken(WorkspaceFactsPort), {
    useFactory: instanceCachingFactory(() => new GitWorkspaceFacts()),
  })

  container.register(portToken(BeforeToolHook), {
    useFactory: (resolver) => {
      const sessions = resolveIfPossible({ container: resolver, token: SessionRegistryToken })
      return new ResolveProjectPathsHook(resolver.resolveAll(portToken(ToolDefinition)), {
        threadEnvironment: sessions === undefined ? undefined : threadEnvironmentFrom({ sessions }),
      })
    },
  })
  container.register(portToken(BeforeToolHook), {
    useFactory: (resolver) =>
      new ReadBeforeWriteHook(
        resolver.resolve(registeredPortToken(FileReadStatePort)),
        resolver.resolveAll(portToken(ToolDefinition)),
        resolver.resolve(registeredPortToken(AgentFileSystemPort)),
      ),
  })
  registerClassifier({ container })
  container.register(portToken(BeforeToolHook), {
    useFactory: (resolver) =>
      new ServiceShapeHook({
        decisions: resolver.isRegistered(registeredPortToken(DecisionPort), true)
          ? resolver.resolve(registeredPortToken(DecisionPort))
          : new JevDecisionClient({ config: () => undefined }),
      }),
  })
  container.register(portToken(BeforeTurnHook), {
    useFactory: (resolver) =>
      new PrewarmFactsHook(
        resolver.resolve(registeredPortToken(WorkspaceFactsPort)),
        resolver.resolve(WorkspaceRoot),
      ),
  })
  container.register(portToken(BeforeTurnHook), {
    useFactory: (resolver) =>
      new SkillSuggestionHook({
        log: resolveIfPossible({ container: resolver, token: registeredPortToken(EventLogPort) }),
        skills: resolveIfPossible({
          container: resolver,
          token: registeredPortToken(SkillRegistryPort),
        }),
        decisions: resolver.isRegistered(registeredPortToken(DecisionPort), true)
          ? resolver.resolve(registeredPortToken(DecisionPort))
          : new JevDecisionClient({ config: () => undefined }),
        enabled: resolver.isRegistered(SkillSuggestionEnabledToken, true)
          ? resolver.resolve(SkillSuggestionEnabledToken)
          : () => false,
      }),
  })
  container.register(portToken(AfterToolHook), {
    useFactory: (resolver) =>
      new RecordFileStateHook(
        resolver.resolve(registeredPortToken(FileReadStatePort)),
        resolver.resolveAll(portToken(ToolDefinition)),
        resolver.resolve(registeredPortToken(AgentFileSystemPort)),
      ),
  })
  container.register(portToken(AfterToolHook), { useClass: MirrorPlanHook })
  container.register(portToken(AfterToolHook), {
    useFactory: (resolver) => {
      const sessions = resolveIfPossible({ container: resolver, token: SessionRegistryToken })
      return new OutsideProjectHook({
        threadEnvironment: sessions === undefined ? undefined : threadEnvironmentFrom({ sessions }),
      })
    },
  })
  container.register(portToken(AfterToolHook), { useClass: TrackWorktreeHook })
  container.register(portToken(AfterToolHook), {
    useFactory: (resolver) => new TrackCheckoutHook(checkoutObserverOf(resolver)),
  })
  container.register(portToken(OnThreadOpenHook), {
    useFactory: (resolver) => new OpenCheckoutHook(checkoutObserverOf(resolver)),
  })
  container.register(portToken(AfterToolHook), {
    useFactory: (resolver) =>
      new InvalidateFactsHook(resolver.resolve(registeredPortToken(WorkspaceFactsPort))),
  })
}
