import { EExecutionLocation, EHarnessPlacement, ERunner, type ThreadId } from '@dltech/atlas-core'
import {
  assemblePodThread,
  birthInCloud,
  EBirthNode,
  storedModel,
  type CloudReload,
  type SessionOwner,
  type SessionRuntime,
} from '@dltech/atlas-harness'

import { ENoticeTone, NOTICE_WARN_MS, notify } from '../../ui/notice-store'
import type { AtlasApp } from '../compose'
import { messageOf } from '../error-text'
import { birthHeading } from '../container-move'
import { cloudBindingOf, prepareOn } from '../session-binding'
import type { BootNarration } from '../boot-block-store'
import type { CloudBridgeFactory } from './bridge-factory'
import { bornPlacementChip, startsTheThread } from './born-placement-chip'
import { podThreadPortsOf } from './cloud-app'
import { localCopyFor } from './cloud-open'
import {
  BIRTH_CANCELLED_NOTICE,
  CLOUD_BIRTH_NOTICE_KEY,
  birthFailedNotice,
} from './cloud-birth-notices'
import { podWakeNarrationOf } from './wake-narration'

const BOOT_LABEL_ROWS = [EBirthNode.Provision, 'waiting']

const warn = (text: string): void =>
  notify({ key: CLOUD_BIRTH_NOTICE_KEY, text, tone: ENoticeTone.Warn, ttlMs: NOTICE_WARN_MS })

export function birthNewborn(args: {
  app: AtlasApp
  owner: SessionOwner<SessionRuntime>
  move: BootNarration
  createBridge: CloudBridgeFactory
  threadId: ThreadId
  runner: ERunner
  projectId: string | null
  onReload: (reload: CloudReload) => Promise<void>
  onRestoreDraft: () => void
  onRelease: () => void
}): void {
  const { app, move, owner, threadId, runner, projectId } = args
  const bridge = args.createBridge({
    runner,
    birth: true,
    onBootStep: ({ label }) => {
      for (const nodeId of BOOT_LABEL_ROWS) move.handleRowLabel({ nodeId, text: label })
    },
  })
  let cancelled = false
  const destroySandbox = (): Promise<void> =>
    bridge.sandboxes.destroy({ threadId }).catch(() => undefined)
  const failed = async (reason: string): Promise<void> => {
    await destroySandbox()
    move.handleFail(reason)
    warn(reason)
    args.onRestoreDraft()
    args.onRelease()
  }
  const settleCancelled = async (): Promise<void> => {
    await destroySandbox()
    args.onRelease()
  }
  const handleCancel = (): void => {
    cancelled = true
    warn(BIRTH_CANCELLED_NOTICE)
    args.onRestoreDraft()
  }

  void birthInCloud({
    threadId,
    runner,
    projectId,
    identity: app.workspace,
    model: storedModel(app.model.choice()),
    bridge,
    localThreads: app.threads,
    ids: app.ids,
    placement: owner,
    onBegin: ({ waves }) =>
      move.handleBegin({
        target: EExecutionLocation.Cloud,
        rows: waves.map((wave) => ({
          id: wave.ids[0] ?? wave.label,
          text: wave.label,
          nodeIds: wave.ids,
        })),
        heading: birthHeading(runner),
        onCancel: handleCancel,
      }),
    onNodeStart: (nodeId) => move.handleNodeStart(nodeId),
    onNodeDone: (nodeId) => move.handleNodeDone(nodeId),
    open: async ({ attachment, prepareRuntime }) => {
      if (cancelled) throw new Error(BIRTH_CANCELLED_NOTICE)
      const stopWatching = attachment.channel.subscribe({
        threadId,
        listener: (signal) => {
          if (!startsTheThread(signal)) return
          stopWatching()
          bornPlacementChip(app).retire(threadId)
        },
      })
      const pod = await assemblePodThread({
        bridge,
        threadId,
        attachment,
        projectId,
        ...podThreadPortsOf({ app, threadId, onReload: args.onReload }),
        localCopy: localCopyFor({ app, runner }),
        wakeNarration: podWakeNarrationOf(move),
        assertStillWanted: () => {
          if (cancelled) throw new Error(BIRTH_CANCELLED_NOTICE)
        },
      })
      prepareOn({ prepareRuntime, binding: cloudBindingOf({ local: app, bridge, pod }) })
    },
  })
    .then((born) => {
      if (cancelled) return settleCancelled()
      if (!born.ok) return failed(birthFailedNotice(born))
      const chip = bornPlacementChip(app)
      const held = chip.snapshot()
      const arrivals = held?.threadId === threadId ? held.arrivals : undefined
      chip.set({
        threadId,
        harness: EHarnessPlacement.Cloud,
        runner,
        provisioning: false,
        arrivals,
      })
      move.handleSettle()
    })
    .catch((error: unknown) => {
      if (cancelled) return settleCancelled()
      return failed(`starting the pod failed — ${messageOf(error)}`)
    })
}
