import {
  AUTO_COMPACT_OFF,
  estimateTokensFor,
  imageTierOf,
  saidBody,
  type Assembled,
  type AssemblyPipeline,
  type ThreadId,
  type ChunkFilter,
  type EventDraft,
  type EventLogPort,
  type SaidFile,
  type SaidImage,
  type SaidUpload,
  type IdPort,
  type LogPort,
  type LoopCut,
  type ModelPort,
  type ToolDeclaration,
} from '@dltech/atlas-core'

import { modelFailureDiagnosticsOf } from '../model/failure-diagnostics'
import { logFieldsOf } from '../store/logs'
import type { HookChain } from '../hooks/registry'
import type { SaidUploadsPort } from '../uploads/said-uploads.port'
import type { ApplyLoopCut } from '../store/sessions/ops/cut-loop'
import type { ToolDispatcher } from '../tools/dispatch'
import type { ModelWaitObserver } from '../model-recovery/wait-state'
import type { LoopWatch } from './loop-watchdog'
import type { PauseSignal } from './pause-signal'
import type { PendingDrain } from './pending-intake'
import type { ExpandContext } from '../pending'
import type { RetryDeps } from './retrying-step'
import type { SleepPrevention } from '../power/sleep-prevention'
import { openTurnSpend, TURN_CRASHED, type TurnLedgerDeps } from '../ledger/record-turn-spend'
import { runFailureOf } from '../model/run-failure'
import { recordEscapedFailure, recordRunFailure } from './recorded-failures'
import { appendResumeDrafts } from './resume-turn'
import { createSettlePending, type OnToolOutputNotice } from './settle-pending'
