import {
  EBeforeToolDecision,
  EToolEffect,
  hookOutcomeDrafts,
  resolveBeforeTool,
  type ActiveWorktree,
  type BeforeTool,
  type BeforeToolOutcome,
  type CallId,
  type ConsultedHook,
  type Event,
  type EventDraft,
  type RunId,
  type ThreadId,
  type ToolCall,
  type ToolDefinition,
  type ToolOutcome,
  type OnToolOutput,
  type WorkspacePort,
  type HookOutcome,
  type LogPort,
  type QualityReviewPort,
} from '@dltech/atlas-core'

import { logFieldsOf } from '../store/logs'
import { withinBudget, type OnHookMishap } from '../hooks/budget'
import type { HookChain, RegisteredHook } from '../hooks/registry'
import {
  invalidInputDraft,
  markDispatchStarted,
  markerFailureDraft,
  unknownToolDraft,
} from './dispatch-drafts'
import { outcomeWhenAHookDidNotAnswerInTime } from './hook-silence'
import { QualityStage } from './quality-dispatch'
import type { ToolRegistry } from './registry'
import { resultDraft } from './tool-result-draft'

export type DispatchableCall = {
  callId: CallId
  name: string
  input: unknown
  runId: RunId
  threadId: ThreadId
}

export type DispatchArgs = {
  call: DispatchableCall
  signal: AbortSignal
  projectDirectory: string
  homeDirectory?: string | undefined
  events: readonly Event[]
  activeWorktree?: ActiveWorktree | undefined
  onOutput?: OnToolOutput | undefined
  onDispatchStarted?: ((draft: EventDraft) => Promise<void>) | undefined
}

export abstract class ToolDispatcher {
  abstract dispatch(args: DispatchArgs): Promise<readonly EventDraft[]>
}

const messageOf = (error: unknown): string =>
  error instanceof Error ? error.message : String(error)

const NO_OUTCOME: HookOutcome = {}

const changesTheWorld = (effect: EToolEffect): boolean =>
  effect === EToolEffect.Write || effect === EToolEffect.Destructive

export class HookedToolDispatcher extends ToolDispatcher {
  private readonly registry: ToolRegistry
  private readonly hooks: HookChain
  private readonly workspace: WorkspacePort | undefined
  private readonly onMishap: OnHookMishap | undefined
  private readonly logPort: LogPort | undefined
  private readonly quality: QualityStage

  constructor(args: {
    registry: ToolRegistry
    hooks: HookChain
    workspace?: WorkspacePort | undefined
    onMishap?: OnHookMishap | undefined
    logPort?: LogPort | undefined
    quality?: QualityReviewPort | undefined
  }) {
    super()
    this.registry = args.registry
    this.hooks = args.hooks
    this.workspace = args.workspace
    this.onMishap = args.onMishap ?? args.hooks.bounds.onMishap
    this.logPort = args.logPort
    this.quality = new QualityStage({ quality: args.quality, logPort: args.logPort })
  }

  async dispatch(args: DispatchArgs): Promise<readonly EventDraft[]> {
    const {
      call,
      signal,
      projectDirectory,
      homeDirectory,
      activeWorktree,
      events,
      onOutput,
      onDispatchStarted,
    } = args
    const definition = this.registry.find(call.name)
    if (definition === undefined) {
      const available = this.registry.declarations().map((declaration) => declaration.name)
      return [unknownToolDraft({ call, available })]
    }

    const parsed = definition.inputSchema.safeParse(call.input)
    if (!parsed.success) return [invalidInputDraft({ call, issues: parsed.error.issues })]

    const candidate: ToolCall = {
      callId: call.callId,
      name: call.name,
      input: parsed.data,
      effect: definition.effect,
      threadId: call.threadId,
    }

    const { outcome, drafts } = resolveBeforeTool({
      call: candidate,
      outcomes: await this.consultBeforeTool({ call: candidate, projectDirectory, events, signal }),
    })

    if (outcome.decision === EBeforeToolDecision.Deny) {
      return [
        ...drafts,
        { type: 'tool-denied', callId: call.callId, name: call.name, reason: outcome.reason },
      ]
    }

    const allowed: ToolCall = { ...candidate, input: outcome.input }
    const idempotencyKey = `${call.runId}:${call.callId}`
    const markerFailure = await markDispatchStarted({
      onDispatchStarted,
      call,
      logPort: this.logPort,
    })
    if (markerFailure !== undefined) {
      return [
        ...drafts,
        markerFailureDraft({ callId: call.callId, name: call.name, failure: markerFailure }),
      ]
    }
    const result = await this.invokeTool({
      definition,
      call: allowed,
      signal,
      idempotencyKey,
      projectDirectory,
      homeDirectory,
      activeWorktree,
      threadId: call.threadId,
      onOutput,
      captureFileChanges: this.quality.captureEnabled({ threadId: call.threadId }),
    })

    const qualityOutcome = await this.quality.review({
      call: allowed,
      runId: call.runId,
      result,
      events,
      projectDirectory,
      signal,
    })

    return [
      ...drafts,
      resultDraft({
        call: allowed,
        result,
        interrupted: signal.aborted,
        qualityReviews: qualityOutcome.reviews,
      }),
      ...(await this.observeAfterTool({ call: allowed, result, projectDirectory, signal })),
      ...(qualityOutcome.nudge === undefined ? [] : [qualityOutcome.nudge]),
    ]
  }

  private async outcomeOf(args: {
    hook: RegisteredHook<BeforeTool>
    call: ToolCall
    projectDirectory: string
    events: readonly Event[]
    signal: AbortSignal
  }): Promise<BeforeToolOutcome> {
    return withinBudget({
      label: args.hook.name,
      run: () =>
        args.hook.run({
          call: args.call,
          projectDirectory: args.projectDirectory,
          events: args.events,
          signal: args.signal,
        }),
      fallback: (mishap) => outcomeWhenAHookDidNotAnswerInTime({ mishap, call: args.call }),
      budgetMs: this.hooks.bounds.budgetMs,
      onMishap: this.onMishap,
    })
  }

  private async consultBeforeTool(args: {
    call: ToolCall
    projectDirectory: string
    events: readonly Event[]
    signal: AbortSignal
  }): Promise<ConsultedHook[]> {
    const consulted: ConsultedHook[] = []
    let input = args.call.input

    for (const hook of this.hooks.beforeTool) {
      const outcome = await this.outcomeOf({
        hook,
        call: { ...args.call, input },
        projectDirectory: args.projectDirectory,
        events: args.events,
        signal: args.signal,
      })
      if (outcome.decision === EBeforeToolDecision.Allow) input = outcome.input
      consulted.push({ hookName: hook.name, outcome })
    }

    return consulted
  }

  private async invokeTool(args: {
    definition: ToolDefinition
    call: ToolCall
    signal: AbortSignal
    idempotencyKey: string
    projectDirectory: string
    homeDirectory: string | undefined
    activeWorktree: ActiveWorktree | undefined
    threadId: ThreadId
    onOutput: OnToolOutput | undefined
    captureFileChanges: boolean
  }): Promise<ToolOutcome> {
    try {
      return await args.definition.invoke({
        input: args.call.input,
        signal: args.signal,
        idempotencyKey: args.idempotencyKey,
        projectDirectory: args.projectDirectory,
        homeDirectory: args.homeDirectory,
        activeWorktree: args.activeWorktree,
        threadId: args.threadId,
        onOutput: args.onOutput,
        ...(args.captureFileChanges ? { captureFileChanges: true } : {}),
      })
    } catch (error) {
      this.logPort?.error({
        source: 'tools.dispatch',
        message: `the ${args.call.name} tool threw`,
        threadId: args.threadId,
        data: { tool: args.call.name },
        ...logFieldsOf({ error }),
      })
      return { ok: false, reason: `the ${args.call.name} tool threw: ${messageOf(error)}` }
    }
  }

  private async observeAfterTool(args: {
    call: ToolCall
    result: ToolOutcome
    projectDirectory: string
    signal: AbortSignal
  }): Promise<EventDraft[]> {
    const observed: EventDraft[] = []

    for (const hook of this.hooks.afterTool) {
      const outcome = await withinBudget({
        label: hook.name,
        run: () =>
          hook.run({
            call: args.call,
            result: args.result,
            projectDirectory: args.projectDirectory,
            signal: args.signal,
          }),
        fallback: () => NO_OUTCOME,
        budgetMs: this.hooks.bounds.budgetMs,
        onMishap: this.onMishap,
      })
      observed.push(...hookOutcomeDrafts({ hookName: hook.name, outcome }))
    }

    return observed
  }
}
