import { useMemo, useSyncExternalStore } from 'react'

import type { LinkedPullRequest } from '@dltech/atlas-core'
import type {
  PluginProjection,
  PullRequestPort,
  PullRequestService,
  RepositoryCheckout,
  SessionFacts,
  UrlOpener,
} from '@dltech/atlas-harness'

import { activePrStateReader } from '../../composition/cloud/pr-state-reader-holder'
import { EFooterItemReach, type FooterItem } from '../../ui/footer-item'
import type { ContributedSurface, PluginSurface } from '../surface'
import { useAppInstallNotice, type AppInstallRecommendationSource } from './app-install-notice'
import { pullRequestChip, pullRequestFallbackChip } from './pull-request-pill'
import type { SubscriptionsAccess } from '../subscriptions/access'
import { usePullRequestBell } from '../subscriptions/use-pull-request-bell'
import { usePullRequest, type FooterPullRequest } from './use-pull-request'

export function pullRequestItem(args: {
  footer: FooterPullRequest | null
  onOpen: (url: string) => void
}): FooterItem | null {
  const { footer } = args
  if (footer === null) return null

  const chip =
    footer.badge === null
      ? pullRequestFallbackChip({ label: footer.label })
      : pullRequestChip(footer.badge)

  const first = chip.spans[0]
  const spans =
    footer.overflow === 0 || first === undefined
      ? chip.spans
      : [{ ...first, text: `${first.text} +${footer.overflow}` }, ...chip.spans.slice(1)]

  return {
    id: 'pr',
    spans,
    ground: chip.ground,
    reach: EFooterItemReach.Keyboard,
    onActivate: () => args.onOpen(footer.url),
  }
}

export const pullRequestSurface = (args: {
  service: PullRequestService
  facts: SessionFacts
  links: PluginProjection<readonly LinkedPullRequest[]>
  cloudCheckout: PluginProjection<RepositoryCheckout | null>
  /** The badge cache behind the muted fallback when a cloud serve is unreachable. */
  badges: PullRequestPort
  openUrl: UrlOpener
  appInstall?: AppInstallRecommendationSource | null
  recordAppInstallDismissal?: (args: { repo: string }) => void
  subscriptions?: SubscriptionsAccess | null
}): ContributedSurface => {
  const { service, facts, links, cloudCheckout, badges, openUrl } = args
  const appInstall = args.appInstall ?? null
  const subscriptions = args.subscriptions ?? null

  return {
    pluginId: 'github',
    use: (): PluginSurface => {
      useSyncExternalStore(facts.subscribe, facts.version)
      useSyncExternalStore(links.subscribe, links.version)
      useSyncExternalStore(cloudCheckout.subscribe, cloudCheckout.version)

      const linked = links.current()
      const projectDirectory = facts.directory()
      const bell = usePullRequestBell({ access: subscriptions, projectDirectory })
      const { footer, section } = usePullRequest({
        service,
        projectDirectory,
        working: facts.working(),
        linked,
        cloud: cloudCheckout.current(),
        remote: activePrStateReader(),
        badges,
        onOpen: openUrl,
        bell,
      })

      useAppInstallNotice({
        source: appInstall,
        ...(args.recordAppInstallDismissal === undefined
          ? {}
          : { recordDismissal: args.recordAppInstallDismissal }),
      })

      const footerItem = useMemo(
        () => pullRequestItem({ footer, onOpen: openUrl }),
        [footer, openUrl],
      )

      return useMemo(() => ({ footerItem, sidebarSection: section }), [footerItem, section])
    },
  }
}
