import {
  agentRoster,
  isLost,
  type ClockPort,
  type EventLogPort,
  type IdPort,
  type ThreadId,
} from '@dltech/atlas-core'

import type { ThreadStorePort } from '../../store'
import type { ModelWaitState } from '../../model-recovery/wait-state'
import { parkWaiting, recoveredChild } from './child-state'
import { requeueOwedNotices, stampSettledDeliveries } from './owed-notices'
import { settleLostChildren, unloggedChildren } from './lost-children'
import type { AgentNoticeQueue } from './notices'
import type { AgentRoster } from './roster'
import type { RecoveredAgents } from './snapshot'
import {
  refreshTransferredFamily,
  storedModelOf,
  type TransferredOwner,
} from './transferred-family'

export class ChildRecovery {
  private readonly log: EventLogPort
  private readonly threads: ThreadStorePort
  private readonly ids: IdPort
  private readonly clock: ClockPort
  private readonly roster: AgentRoster
  private readonly notices: AgentNoticeQueue
  private readonly launchDirectory: string
  private readonly waitState: Pick<ModelWaitState, 'episodeOf'> | undefined
  private readonly hydrating = new Map<ThreadId, Promise<void>>()
  private readonly settling = new Map<ThreadId, Promise<RecoveredAgents>>()

  constructor(args: {
    log: EventLogPort
    threads: ThreadStorePort
    ids: IdPort
    clock: ClockPort
    roster: AgentRoster
    notices: AgentNoticeQueue
    launchDirectory: string
    waitState?: Pick<ModelWaitState, 'episodeOf'> | undefined
  }) {
    this.log = args.log
    this.threads = args.threads
    this.ids = args.ids
    this.clock = args.clock
    this.roster = args.roster
    this.notices = args.notices
    this.launchDirectory = args.launchDirectory
    this.waitState = args.waitState
  }

  /**
   * A child outlives the process that spawned it, because its thread and its rows do. The parent's
   * own log is the whole record, so a restart rebuilds the roster from it rather than from a side
   * table; this is deliberately not done at construction, where a container resolve would block on
   * the database.
   */
  hydrate({ threadId }: { threadId: ThreadId }): Promise<void> {
    const started = this.hydrating.get(threadId)
    if (started !== undefined) return started

    const running = this.rebuild({ threadId })
    this.hydrating.set(threadId, running)
    running.catch(() => {
      if (this.hydrating.get(threadId) === running) this.hydrating.delete(threadId)
    })

    return running
  }

  /**
   * A family that arrived from another location replaces what this process rebuilt before it
   * moved: the memo is dropped and every child the incoming logs name is revised to what they
   * say, with no event written. Whatever hydration was already running finishes first so it can
   * never land over the incoming state.
   */
  hydrateTransferred({ threadId }: { threadId: ThreadId }): Promise<readonly TransferredOwner[]> {
    const prior = this.hydrating.get(threadId) ?? Promise.resolve()
    const attempt = prior
      .catch(() => undefined)
      .then(() =>
        refreshTransferredFamily({
          threadId,
          log: this.log,
          threads: this.threads,
          clock: this.clock,
          roster: this.roster,
          notices: this.notices,
          launchDirectory: this.launchDirectory,
        }),
      )
    const memo = attempt.then(() => undefined)
    this.hydrating.set(threadId, memo)
    memo.catch(() => {
      if (this.hydrating.get(threadId) === memo) this.hydrating.delete(threadId)
    })

    return attempt.then(async (owners) => {
      for (const owner of owners) {
        this.notices.forgetAgents({ threadId: owner.threadId, agentIds: owner.agentIds })
        const events = await this.log.readOwn({ threadId: owner.threadId })
        stampSettledDeliveries({ events, threadId: owner.threadId, roster: this.roster })
        requeueOwedNotices({
          events,
          threadId: owner.threadId,
          roster: this.roster,
          notices: this.notices,
        })
      }
      for (const owner of owners) {
        if (owner.threadId !== threadId) this.hydrating.set(owner.threadId, Promise.resolve())
      }
      return owners
    })
  }

  /**
   * Rebuilding only reads; this writes. A child the process lost has no ending in its parent's log
   * and nothing else will ever write one, so the record stays a lie, and the parent cannot be
   * rewound below the spawn, until someone settles it deliberately.
   *
   * The two kinds are not the same repair. A lost child is a spawn the parent recorded and an
   * ending nobody lived to write, so this completes the record. An unlogged child is a thread the
   * parent never recorded at all, and it is only reported.
   */
  recordLost({ threadId }: { threadId: ThreadId }): Promise<RecoveredAgents> {
    const running = this.settling.get(threadId)
    if (running !== undefined) return running

    const attempt = this.settle({ threadId }).finally(() => {
      this.settling.delete(threadId)
    })
    this.settling.set(threadId, attempt)
    return attempt
  }

  private async settle({ threadId }: { threadId: ThreadId }): Promise<RecoveredAgents> {
    await this.hydrate({ threadId })

    const mine = this.roster.states().filter((child) => child.spawnedBy === threadId)
    const settled = await settleLostChildren({
      log: this.log,
      ids: this.ids,
      clock: this.clock,
      children: mine,
      threadId,
    })
    if (settled.length > 0) this.roster.changed()

    const unlogged = await unloggedChildren({
      threads: this.threads,
      threadId,
      known: new Set(mine.map((child) => child.agentId)),
    })

    return { settled, unlogged }
  }

  private async rebuild({ threadId }: { threadId: ThreadId }): Promise<void> {
    const events = await this.log.readOwn({ threadId })
    const at = this.clock.now()

    for (const agent of agentRoster({ events, threadId })) {
      if (this.roster.find(agent.agentId) !== undefined) continue
      const child = recoveredChild({ agent, spawnedBy: threadId, at })
      const model = await storedModelOf({ threads: this.threads, agentId: agent.agentId })
      if (model !== undefined) child.model = model
      if (isLost(agent)) {
        const episode = await this.waitState?.episodeOf({ threadId: agent.agentId })
        if (episode !== undefined) parkWaiting({ child, episode })
      }
      this.roster.add(child)
    }

    stampSettledDeliveries({ events, threadId, roster: this.roster })
    requeueOwedNotices({ events, threadId, roster: this.roster, notices: this.notices })
  }
}
