import {
  EMessageOrigin,
  saidBody,
  type EventDraft,
  type SaidFile,
  type SaidImage,
  type SaidUpload,
} from '@dltech/atlas-core'
import { EPendingEdit } from '@dltech/atlas-wire'
import type { InputBatch } from '../intake/input-batch'

export type PendingSaid = {
  text: string
  images: readonly SaidImage[]
  files: readonly SaidFile[]
  uploads?: readonly SaidUpload[] | undefined
  context?: readonly EventDraft[] | undefined
  via?: EMessageOrigin | undefined
  requestId?: string | undefined
}

export type PendingMessage = PendingSaid & { kind: 'message'; id: string }

export type PendingCommand<Command> = {
  kind: 'command'
  id: string
  text: string
  command: Command
}

export type PendingEntry<Command> = PendingMessage | PendingCommand<Command>

export type PendingQueue<Command = never> = {
  subscribe(listener: () => void): () => void
  getSnapshot(): readonly PendingEntry<Command>[]
  reserved(entryId: string): boolean
  enqueue(args: {
    text: string
    images?: readonly SaidImage[]
    files?: readonly SaidFile[]
    uploads?: readonly SaidUpload[] | undefined
    context?: readonly EventDraft[] | undefined
    via?: EMessageOrigin | undefined
    requestId?: string | undefined
  }): void
  prepare(): InputBatch
  enqueueCommand(args: { text: string; command: Command }): void
  takeBackLast(): PendingSaid | null
  update(args: { id: string; text: string }): EPendingEdit
  remove(args: { id: string }): EPendingEdit
  drain(): readonly PendingSaid[]
  drainCommands(): readonly PendingCommand<Command>[]
}

const NOTHING_PENDING: readonly PendingEntry<never>[] = Object.freeze([])

const NOTHING_TAKEN: readonly PendingSaid[] = Object.freeze([])

const NO_COMMANDS: readonly PendingCommand<never>[] = Object.freeze([])

const NO_IMAGES: readonly SaidImage[] = Object.freeze([])

const NO_FILES: readonly SaidFile[] = Object.freeze([])

const isOperatorMessage = <Command>(entry: PendingEntry<Command>): entry is PendingMessage =>
  entry.kind === 'message' && (entry.via === undefined || entry.via === EMessageOrigin.Operator)

const isCommand = <Command>(entry: PendingEntry<Command>): entry is PendingCommand<Command> =>
  entry.kind === 'command'

export type ExpandContext = (args: {
  text: string
  context: readonly EventDraft[]
}) => readonly EventDraft[]

export const NO_EXPANSION: ExpandContext = () => []

export function createPendingQueue<Command = never>(
  options: { expandContext?: ExpandContext } = {},
): PendingQueue<Command> {
  const expandContext = options.expandContext ?? NO_EXPANSION
  const contextOf = (message: PendingMessage): readonly EventDraft[] => {
    const context = message.context ?? []
    if (!isOperatorMessage(message)) return context
    return [...context, ...expandContext({ text: message.text, context })]
  }

  let entries: readonly PendingEntry<Command>[] = NOTHING_PENDING
  let snapshot: readonly PendingEntry<Command>[] = entries
  let stamped = 0

  const listeners = new Set<() => void>()
  const reserved = new Set<string>()

  const settle = (next: readonly PendingEntry<Command>[]): void => {
    entries = next
    snapshot = entries
    for (const listener of [...listeners]) listener()
  }

  const stamp = (): string => {
    stamped += 1
    return `pending-${stamped}`
  }

  return {
    subscribe(listener) {
      listeners.add(listener)
      return () => void listeners.delete(listener)
    },

    getSnapshot: () => snapshot,

    reserved: (entryId) => reserved.has(entryId),

    enqueue({ text, images, files, uploads, context, via, requestId }) {
      settle([
        ...entries,
        {
          kind: 'message',
          id: stamp(),
          text,
          images: images ?? NO_IMAGES,
          files: files ?? NO_FILES,
          ...(uploads === undefined || uploads.length === 0 ? {} : { uploads }),
          ...(context === undefined ? {} : { context }),
          ...(via === undefined ? {} : { via }),
          ...(requestId === undefined ? {} : { requestId }),
        },
      ])
    },

    enqueueCommand({ text, command }) {
      settle([...entries, { kind: 'command', id: stamp(), text, command }])
    },

    takeBackLast() {
      const last = [...entries]
        .reverse()
        .find(
          (entry) =>
            !reserved.has(entry.id) &&
            (!('via' in entry) || entry.via === undefined || entry.via === EMessageOrigin.Operator),
        )
      if (last === undefined) return null

      settle(entries.filter((entry) => entry.id !== last.id))
      if (last.kind === 'command') return { text: last.text, images: NO_IMAGES, files: NO_FILES }
      const { kind, id, ...said } = last
      return said
    },

    update({ id, text }) {
      const held = entries.find((entry) => entry.id === id)
      if (held === undefined) return EPendingEdit.Missing
      if (reserved.has(id)) return EPendingEdit.Reserved
      if (!isOperatorMessage(held)) return EPendingEdit.NotEditable

      settle(entries.map((entry) => (entry.id === id ? { ...held, text } : entry)))
      return EPendingEdit.Done
    },

    remove({ id }) {
      const held = entries.find((entry) => entry.id === id)
      if (held === undefined) return EPendingEdit.Missing
      if (reserved.has(id)) return EPendingEdit.Reserved
      if (held.kind === 'message' && !isOperatorMessage(held)) return EPendingEdit.NotEditable

      settle(entries.filter((entry) => entry.id !== id))
      return EPendingEdit.Done
    },

    prepare() {
      const messages = entries.filter(
        (entry): entry is PendingMessage => entry.kind === 'message' && !reserved.has(entry.id),
      )
      for (const message of messages) reserved.add(message.id)
      let settled = false
      const release = (): void => {
        for (const message of messages) reserved.delete(message.id)
      }
      return {
        drafts: messages.flatMap((message): readonly EventDraft[] => [
          ...contextOf(message),
          { ...saidBody(message), ...(message.via === undefined ? {} : { via: message.via }) },
        ]),
        wakesTurn: messages.length > 0,
        acknowledge: () => {
          if (settled) return
          settled = true
          release()
          if (messages.length === 0) return
          const handed = new Set(messages.map((message) => message.id))
          settle(entries.filter((entry) => !handed.has(entry.id)))
        },
        release: () => {
          if (settled) return
          settled = true
          release()
        },
      }
    },

    drain() {
      const messages = entries.filter(
        (entry): entry is PendingMessage => entry.kind === 'message' && !reserved.has(entry.id),
      )
      if (messages.length === 0) return NOTHING_TAKEN

      const handed = new Set(messages.map((message) => message.id))
      settle(entries.filter((entry) => !handed.has(entry.id)))
      return messages.map((message) => {
        const { id, kind, ...said } = message
        return said
      })
    },

    drainCommands() {
      const commands = entries.filter(isCommand)
      if (commands.length === 0) return NO_COMMANDS

      settle(entries.filter((entry) => !isCommand(entry)))
      return commands
    },
  }
}
