import {
  AgentFileSystemPort,
  EExecutionLocation,
  DynamicToolSource,
  EventLogPort,
  FileCapabilitiesPort,
  FileSystemPort,
  IdPort,
  LogPort,
  ProcessPort,
  ToolDefinition,
  type ThreadId,
} from '@dltech/atlas-core'

import { cloudConfigAccessOf } from '../cloud/cloud-config-access'
import { AgentRegistryPort } from '../agents/registry/port'
import { withDeltaPublishing } from '../channel/publishing-event-log'
import { ExecutionLocationToken } from '../composition/execution-location-state'
import {
  portToken,
  registeredPortToken,
  resolveSet,
  type DependencyContainer,
} from '../container/injection'
import { OperatorInputPort } from '../operator-input/port'
import {
  DeltaChannelToken,
  ClientVersionToken,
  CloudSessionStoreToken,
  DockerEngineToken,
  SecretsStoreToken,
  ServeSessionToken,
  SessionRegistryToken,
  WebSearchBackendToken,
  WorktreeDirectoryToken,
  WorkspaceRoot,
} from '../container/tokens'
import { FileWriteGuardPort } from '../files/write-guard'
import { ServiceRegistryPort } from '../services/service-registry'
import { ShellRegistryPort } from '../shells/shell-registry'
import { SkillRegistryPort } from '../skills/port'
import { registerSubscriptionTools } from '../subscriptions/register'
import { ThreadStorePort } from '../store/thread-store'

import { CompositeToolRegistry } from './composite-registry'
import { AgentRegistrySourceToken, AgentTypesToken } from './builtin/agent-tokens'
import { AgentListTool } from './builtin/agent-list'
import { AgentSayTool } from './builtin/agent-say'
import { AgentSpawnTool } from './builtin/agent-spawn'
import { AgentStopTool } from './builtin/agent-stop'
import { ReportToMainTool } from './builtin/report-to-main'
import { BashTool } from './builtin/bash'
import { EditTool } from './builtin/edit'
import { EnterWorktreeTool } from './builtin/enter-worktree'
import { ExecutionLocationTool } from './builtin/execution-location'
import { ExitWorktreeTool } from './builtin/exit-worktree'
import { GlobTool } from './builtin/glob'
import { GrepTool } from './builtin/grep'
import { CloudConfigTool } from './builtin/cloud-config'
import { McpEditTool } from './builtin/mcp-edit'
import { MultiEditTool } from './builtin/multi-edit'
import { ReadTool } from './builtin/read'
import { ServiceListTool } from './builtin/service-list'
import { ServiceStartTool } from './builtin/service-start'
import { ServiceRestartTool } from './builtin/service-restart'
import { ServiceStopTool } from './builtin/service-stop'
import { ServicesEnsureTool } from './builtin/services-ensure'
import { ShellKillTool } from './builtin/shell-kill'
import { ShellListTool } from './builtin/shell-list'
import { ShellOutputTool } from './builtin/shell-output'
import { ShellInputTool } from './builtin/shell-input'
import { OperatorInputTool } from './builtin/operator-input'
import { OperatorShellInputTool } from './builtin/operator-shell-input'
import { SkillTool } from './builtin/skill'
import { SkillInstallTool } from './builtin/skill-install'
import { TaskWriteTool } from './builtin/task-write'
import { WebFetchTool } from './builtin/web-fetch'
import { WebSearchTool } from './builtin/web-search'
import { WriteTool } from './builtin/write'
import { WorktreeListTool } from './builtin/worktree-list'
import { InMemoryToolRegistry, ToolRegistry } from './registry'

const relocationLog = (resolver: DependencyContainer): EventLogPort => {
  const log = resolver.resolve(registeredPortToken(EventLogPort))
  if (!resolver.isRegistered(DeltaChannelToken, true)) return log
  return withDeltaPublishing({ log, channel: resolver.resolve(DeltaChannelToken) })
}

export function registerBuiltinTools({ container }: { container: DependencyContainer }): void {
  const shellRegistry = (resolver: DependencyContainer) =>
    resolver.resolve(registeredPortToken(ShellRegistryPort))
  const serviceRegistry = (resolver: DependencyContainer) =>
    resolver.resolve(registeredPortToken(ServiceRegistryPort))
  const agentRegistry = (resolver: DependencyContainer) =>
    resolver.resolve(AgentRegistrySourceToken)
  const sessionDirFor = (resolver: DependencyContainer) => {
    if (!resolver.isRegistered(SessionRegistryToken, true)) return undefined
    const registry = resolver.resolve(SessionRegistryToken)
    return async (threadId: ThreadId) =>
      await registry.sessionDirFor({ threadId }).catch(() => undefined)
  }

  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) =>
      new ReadTool({
        files: resolver.resolve(registeredPortToken(AgentFileSystemPort)),
        fileCapabilities: resolver.resolve(registeredPortToken(FileCapabilitiesPort)),
        sessionDirFor: sessionDirFor(resolver),
      }),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) =>
      new WriteTool(
        resolver.resolve(registeredPortToken(FileWriteGuardPort)),
        resolver.resolve(registeredPortToken(AgentFileSystemPort)),
      ),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) =>
      new EditTool(
        resolver.resolve(registeredPortToken(FileWriteGuardPort)),
        resolver.resolve(registeredPortToken(AgentFileSystemPort)),
      ),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) =>
      new MultiEditTool(
        resolver.resolve(registeredPortToken(FileWriteGuardPort)),
        resolver.resolve(registeredPortToken(AgentFileSystemPort)),
      ),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) =>
      new BashTool(
        shellRegistry(resolver),
        resolver.resolve(registeredPortToken(FileSystemPort)),
        resolver.resolve(registeredPortToken(ProcessPort)),
      ),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) =>
      new GrepTool(
        resolver.resolve(registeredPortToken(ProcessPort)),
        resolver.resolve(registeredPortToken(AgentFileSystemPort)),
      ),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) =>
      new GlobTool(resolver.resolve(registeredPortToken(AgentFileSystemPort))),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) => new ShellListTool(shellRegistry(resolver)),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) => new ShellOutputTool(shellRegistry(resolver)),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) => new ShellKillTool(shellRegistry(resolver)),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) => new ShellInputTool(shellRegistry(resolver)),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) =>
      new OperatorInputTool({
        operatorInput: resolver.resolve(registeredPortToken(OperatorInputPort)),
        threads: resolver.resolve(registeredPortToken(ThreadStorePort)),
      }),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) =>
      new OperatorShellInputTool({
        operatorInput: resolver.resolve(registeredPortToken(OperatorInputPort)),
        threads: resolver.resolve(registeredPortToken(ThreadStorePort)),
      }),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) =>
      new ServiceStartTool(
        serviceRegistry(resolver),
        resolver.resolve(registeredPortToken(ProcessPort)),
      ),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) => new ServiceStopTool(serviceRegistry(resolver)),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) => new ServiceListTool(serviceRegistry(resolver)),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) => new ServicesEnsureTool(serviceRegistry(resolver)),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) => new ServiceRestartTool(serviceRegistry(resolver)),
  })
  container.register(portToken(ToolDefinition), { useClass: TaskWriteTool })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) =>
      new SkillTool(resolver.resolve(registeredPortToken(SkillRegistryPort))),
  })
  container.register(portToken(ToolDefinition), { useClass: SkillInstallTool })
  container.register(portToken(ToolDefinition), { useClass: McpEditTool })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) =>
      new CloudConfigTool(
        cloudConfigAccessOf({
          serveSession: resolver.isRegistered(ServeSessionToken, true)
            ? resolver.resolve(ServeSessionToken)
            : null,
          sessionStore: resolver.isRegistered(CloudSessionStoreToken, true)
            ? resolver.resolve(CloudSessionStoreToken)
            : null,
          threads: resolver.resolve(registeredPortToken(ThreadStorePort)),
          clientVersion: resolver.isRegistered(ClientVersionToken, true)
            ? resolver.resolve(ClientVersionToken)
            : 'dev',
        }),
      ),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) =>
      new AgentSpawnTool(agentRegistry(resolver), resolver.resolve(AgentTypesToken)),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) => new AgentSayTool(agentRegistry(resolver)),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) => new AgentListTool(agentRegistry(resolver)),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) => new AgentStopTool(agentRegistry(resolver)),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) => new ReportToMainTool(agentRegistry(resolver)),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) =>
      new EnterWorktreeTool(
        resolver.resolve(WorkspaceRoot),
        resolver.resolve(WorktreeDirectoryToken),
      ),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) => new ExitWorktreeTool(resolver.resolve(WorkspaceRoot)),
  })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) =>
      new ExecutionLocationTool({
        control: resolver.resolve(ExecutionLocationToken),
        engine: resolver.resolve(DockerEngineToken),
        ids: resolver.resolve(registeredPortToken(IdPort)),
        services: serviceRegistry(resolver),
        shells: shellRegistry(resolver),
        stores: () => ({
          threads: resolver.resolve(registeredPortToken(ThreadStorePort)),
          log: relocationLog(resolver),
          agents: resolver.resolve(registeredPortToken(AgentRegistryPort)),
        }),
        logPort: resolver.resolve(registeredPortToken(LogPort)),
      }),
  })
  registerSubscriptionTools({ container })
  container.register(portToken(ToolDefinition), { useClass: WorktreeListTool })
  container.register(portToken(ToolDefinition), { useClass: WebFetchTool })
  container.register(portToken(ToolDefinition), {
    useFactory: (resolver) =>
      new WebSearchTool(
        resolver.resolve(WebSearchBackendToken),
        resolver.resolve(SecretsStoreToken),
      ),
  })

  container.register(registeredPortToken(ToolRegistry), {
    useFactory: (resolver) =>
      new CompositeToolRegistry({
        base: new InMemoryToolRegistry(resolver.resolveAll(portToken(ToolDefinition))),
        sources: resolveSet({ container: resolver, token: portToken(DynamicToolSource) }),
        available: (name) =>
          name !== 'execution_location' ||
          resolver.resolve(ExecutionLocationToken).state.current() !== EExecutionLocation.Cloud,
      }),
  })
}
