import { RGBA, StyledText, type TextChunk } from '@opentui/core'

import { mixHex } from './colour'
import { cellsOf } from './hint-layout'
import { theme } from './theme'

export const NAMING_SETTLE_MS = 400

const NOISE = '····:∙'

const randomNoise = (): string => NOISE[Math.floor(Math.random() * NOISE.length)] ?? '·'

const rgba = new Map<string, RGBA>()

const mixed = new Map<string, string>()

function colourOf(args: { from: string; to: string; amount: number }): RGBA {
  const amount = Math.round(args.amount * 255) / 255
  const key = `${args.from}${args.to}${amount}`
  const held = mixed.get(key)
  if (held !== undefined) return rgbaOf(held)
  const next = mixHex({ from: args.from, to: args.to, amount })
  mixed.set(key, next)
  return rgbaOf(next)
}

function rgbaOf(hex: string): RGBA {
  const held = rgba.get(hex)
  if (held !== undefined) return held
  const next = RGBA.fromHex(hex)
  rgba.set(hex, next)
  return next
}

export type NamingLine = {
  fg: string
  towards: string
  dim: number
  bg?: string | undefined
}

const chunk = (text: string, fg: RGBA, bg: string | undefined): TextChunk => ({
  __isChunk: true,
  text,
  fg,
  ...(bg === undefined ? {} : { bg: rgbaOf(bg) }),
})

/**
 * The cushion a slab-backed line keeps around its glyphs: one cell of ground on each side, the
 * same ` ${title} ` the settled title in that seat renders. Lines with no ground of their own
 * (the sidebar) paint flush, so the pad follows `bg`, not the caller.
 */
const pad = (text: string, bg: string | undefined): string =>
  bg === undefined ? text : ` ${text} `

const padChunks = (chunks: TextChunk[], args: { fg: RGBA; bg: string | undefined }): TextChunk[] =>
  args.bg === undefined
    ? chunks
    : [chunk(' ', args.fg, args.bg), ...chunks, chunk(' ', args.fg, args.bg)]

/**
 * The generating phase: a line of noise dots reshuffled every tick, dimmed toward the ground the
 * title sits on. It never settles — the answer arriving is what ends it.
 */
export function namingGenerating(args: { startCells: number; line: NamingLine }): StyledText {
  const dimmed = colourOf({ from: args.line.fg, to: args.line.towards, amount: args.line.dim })
  return new StyledText(
    padChunks(
      Array.from({ length: Math.max(0, args.startCells) }, () =>
        chunk(randomNoise(), dimmed, args.line.bg),
      ),
      { fg: dimmed, bg: args.line.bg },
    ),
  )
}

/**
 * The streaming phase: the answer is in, so its final width is known. Letters resolve left to
 * right while the line's whole width glides from the width the generating phase held to the
 * title's own — a rename never shifts content, and a first name shrinks or grows into place
 * instead of snapping at the end.
 */
export function namingStreaming(args: {
  title: string
  startCells: number
  line: NamingLine
  now: number
  startedAt: number
}): StyledText {
  const padded = args.line.bg !== undefined
  const title = [...(padded ? ` ${args.title} ` : args.title)]
  const progress = Math.max(0, Math.min(1, (args.now - args.startedAt) / NAMING_SETTLE_MS))
  const settled = Math.floor(progress * title.length)
  const cells = Math.max(
    1,
    Math.round(args.startCells + (title.length - args.startCells) * progress),
  )

  const settledFg = rgbaOf(args.line.fg)
  const noiseFg = colourOf({ from: args.line.fg, to: args.line.towards, amount: args.line.dim })

  /**
   * The sweep resolves the title's letters while the slab's pad cells hold their ground from the
   * first frame: a letter past the sweep is noise, a pad cell is itself, so the cushion the
   * settled title keeps never pops in only when the sweep ends. A line with no ground of its own
   * (the sidebar) has no pad, so nothing here moves for it.
   */
  const holdsPad = (index: number): boolean => padded && (index === 0 || index === title.length - 1)

  const chunks: TextChunk[] = []
  for (let index = 0; index < cells; index++) {
    if (holdsPad(index)) chunks.push(chunk(title[index] ?? ' ', settledFg, args.line.bg))
    else if (index < settled) chunks.push(chunk(title[index] ?? ' ', settledFg, args.line.bg))
    else chunks.push(chunk(randomNoise(), noiseFg, args.line.bg))
  }
  return new StyledText(chunks)
}

/**
 * A settled title drawn through the same path as the streaming phase, so a settle that lands
 * mid-frame never repaints differently from the frame before it.
 */
export function namingSettled(args: { title: string; line: NamingLine }): StyledText {
  return new StyledText([chunk(pad(args.title, args.line.bg), rgbaOf(args.line.fg), args.line.bg)])
}

/**
 * The one pure piece: how many cells the streaming line holds at a given progress. Everything else
 * is noise and colour; this is the glide.
 */
export function namingGlideCells(args: {
  startCells: number
  finalCells: number
  progress: number
}): number {
  return Math.max(
    1,
    Math.round(
      args.startCells +
        (args.finalCells - args.startCells) * Math.max(0, Math.min(1, args.progress)),
    ),
  )
}

/** The composer slab reads its title in cells the same way the painters do. */
export const titleCells = (title: string): number => cellsOf(title)

/**
 * Where a first name's generating line opens when there is no old name to continue from: the
 * average session title, measured across the real session store (576 titles: mean 28.5, median 29,
 * capped at 48 by the titler's own character limit). A fixed count, not a fraction of the row, so a
 * wide composer does not open a slab of noise half the screen across; `min` with the row is what
 * flexes it down when the tile narrows.
 */
export const FRESH_TITLE_CELLS = 28

/**
 * Where the generating line starts when there is no old name to continue from: the sidebar takes
 * its whole row, the composer the average title — so the glide expands or contracts about as often
 * as either.
 */
export function freshStartCells(args: { kind: 'sidebar' | 'composer'; maxCells: number }): number {
  if (args.kind === 'sidebar') return args.maxCells
  return Math.max(1, Math.min(FRESH_TITLE_CELLS, args.maxCells))
}

export const NAMING_SIDEBAR_LINE: NamingLine = { fg: theme.bright, towards: theme.appBg, dim: 0.45 }

export const namingComposerLine = (args: {
  fg: string
  towards: string
  bg?: string
}): NamingLine => ({
  fg: args.fg,
  towards: args.towards,
  dim: 0.35,
  ...(args.bg === undefined ? {} : { bg: args.bg }),
})
